// connError represents an HTTP/2 ConnectionError error code, along
// with a string (for debugging) explaining why.
//
// Errors of this type are only returned by the frame parser functions
// and converted into ConnectionError(Code), after stashing away
// the Reason into the Framer's errDetail field, accessible via
// the (*Framer).ErrorDetail method.
type connError struct {
	Code   http2.ErrCode // the ConnectionError error code
	Reason string        // additional reason
}

func (e connError) Error() string {
	return fmt.Sprintf("http2: connection error: %v: %v", e.Code, e.Reason)
}

// FrameError represents an error that occurred during frame processing,
// including diagnostic information about the frame.
type FrameError struct {
	FrameType http2.FrameType
	StreamID  uint32
	Code      http2.ErrCode
	Reason    string
}

func (e *FrameError) Error() string {
	return fmt.Sprintf("http2: frame error [type=%v, streamID=%d, code=%v]: %s",
		e.FrameType, e.StreamID, e.Code, e.Reason)
}

// Dump returns a detailed diagnostic dump of the frame error.
func (e *FrameError) Dump() string {
	return fmt.Sprintf("FrameError Diagnostics:\n"+
		"  Frame Type: %v (%d)\n"+
		"  Stream ID: %d\n"+
		"  Error Code: %v\n"+
		"  Reason: %s\n",
		e.FrameType, e.FrameType, e.StreamID, e.Code, e.Reason)
}

// NewFrameError creates a new FrameError with the given parameters.
func NewFrameError(frameType http2.FrameType, streamID uint32, code http2.ErrCode, reason string) *FrameError {
	return &FrameError{
		FrameType: frameType,
		StreamID:  streamID,
		Code:      code,
		Reason:    reason,
	}
}

