func (tp Protocol) String() string {
	// Handle zero case
	if tp == 0 {
		return "PurePayload"
	}

	// Define all single-bit flags in ascending bit order
	flags := []struct {
		bit  Protocol
		name string
	}{
		{TTHeader, "TTHeader"},
		{Framed, "Framed"},
		{HTTP, "HTTP"},
		{GRPC, "GRPC"},
		{HESSIAN2, "Hessian2"},
		{TTHeaderStreaming, "TTHeaderStreaming"},
		{GRPCStreaming, "GRPCStreaming"},
	}

	var parts []string
	remaining := tp

	// Check each flag in ascending bit order
	for _, flag := range flags {
		if tp&flag.bit != 0 {
			parts = append(parts, flag.name)
			remaining &^= flag.bit
		}
	}

	// If we matched all bits, return the composite
	if remaining == 0 && len(parts) > 0 {
		if len(parts) == 1 {
			return parts[0]
		}
		result := ""
		for i, part := range parts {
			if i > 0 {
				result += "|"
			}
			result += part
		}
		return result
	}

	return Unknown
}

