		if tp&flag.bit != 0 {
			parts = append(parts, flag.name)
			remaining &^= flag.bit
		}
	}

	// If we matched all bits, return the composite
	if remaining == 0 && len(parts) > 0 {
		if len(parts) == 1 {
			return parts[0]
		}
		result := ""
		for i, part := range parts {
			if i > 0 {
				result += "|"
			}
			result += part
		}
		return result
	}

	return Unknown
}

